<?php
require_once __DIR__.'/config/auth.php';
$user=require_login();
$title='Archives'; require __DIR__.'/includes/header.php';
$q=trim((string)($_GET['q']??''));$from=(string)($_GET['from']??'');$to=(string)($_GET['to']??'');$page=max(1,(int)($_GET['page']??1));$limit=15;$where=[];$params=[];
if($q!==''){ $where[]='(a.ref_number LIKE ? OR p.sender_name LIKE ? OR p.sender_phone LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like);log_activity('search','archive',null,null,'term='.substr($q,0,150),$user); }
if($from!==''){$where[]='DATE(a.created_at)>=?';$params[]=$from;}if($to!==''){$where[]='DATE(a.created_at)<=?';$params[]=$to;}$condition=$where?'WHERE '.implode(' AND ',$where):'';
$s=db()->prepare("SELECT COUNT(*) FROM archives a LEFT JOIN payments p ON p.archive_id=a.id $condition");$s->execute($params);$total=(int)$s->fetchColumn();$pages=max(1,(int)ceil($total/$limit));$page=min($page,$pages);$offset=($page-1)*$limit;
$sql="SELECT a.id,a.ref_number,a.created_at,u.full_name AS entered_by,p.sender_name,p.amount,(SELECT COUNT(*) FROM archive_documents d WHERE d.archive_id=a.id) document_count FROM archives a LEFT JOIN payments p ON p.archive_id=a.id LEFT JOIN users u ON u.id=a.created_by $condition ORDER BY a.created_at DESC LIMIT $limit OFFSET $offset";$s=db()->prepare($sql);$s->execute($params);$rows=$s->fetchAll();$buyerLabel='Buyer';
?><div class="page-head"><div><h1>Archives</h1><p class="muted">Search by reference no, payer name or phone.</p></div><a class="btn" href="archive_add.php">Add archive</a></div><form class="search" method="get"><input name="q" value="<?=e($q)?>" placeholder="Search by reference no, payer name or phone"><input type="date" name="from" value="<?=e($from)?>" aria-label="From date"><input type="date" name="to" value="<?=e($to)?>" aria-label="To date"><button class="btn">Search</button><?php if($q||$from||$to):?><a class="btn light" href="archive_list.php">Clear</a><?php endif;?></form><div class="card table-wrap"><table class="table"><thead><tr><th>Reference No</th><th><?=e($buyerLabel)?></th><th>Documents</th><th>Amount</th><th>Date</th><th>Entered by</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td data-label="Reference No"><strong><?=e($r['ref_number'])?></strong></td><td data-label="Buyer"><?=e($r['sender_name']??'-')?></td><td data-label="Documents"><?=e((string)$r['document_count'])?></td><td data-label="Amount"><?=($r['amount']!==null?e(CURRENCY.number_format((float)$r['amount'],2)):'-')?></td><td data-label="Date"><?=e(date('M j, Y',strtotime($r['created_at'])))?></td><td data-label="Entered by"><?=e($r['entered_by']??'-')?></td><td data-label="Actions"><div class="actions"><a class="btn light" href="archive_view.php?id=<?=$r['id']?>">View</a><?php if($user['role']==='admin'):?><a class="btn light" href="archive_edit.php?id=<?=$r['id']?>">Edit</a><form method="post" action="archive_delete.php" data-confirm="Delete this archive and its documents?"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger">Delete</button></form><?php endif;?></div></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7" class="empty">No archives found.</td></tr><?php endif;?></tbody></table></div><?php if($pages>1):?><nav class="pagination" aria-label="Archive pages"><?php for($p=1;$p<=$pages;$p++):?><a class="btn <?=($p===$page?'':'light')?>" href="?q=<?=urlencode($q)?>&from=<?=urlencode($from)?>&to=<?=urlencode($to)?>&page=<?=$p?>"><?=$p?></a><?php endfor;?></nav><?php endif;?><?php require __DIR__.'/includes/footer.php';
